"""Generates ../pydigit_table.go: the characters for which str.isdigit() is
true but str.isdecimal() is not (superscripts, circled digits ...), of the
Python running this script (CPython 3.11, Unicode 14). Used for the Mihomo
panel's log cursor (`after.isdigit()`).

    rt -- bash -lc 'cd server/internal/agents/monitor && ~/cf-test/.venv/bin/python testdata/gen_digit.py > pydigit_table.go'
"""
import sys
import unicodedata

extra = [cp for cp in range(sys.maxunicode + 1) if chr(cp).isdigit() and not chr(cp).isdecimal()]
print('// Code generated by testdata/gen_digit.py (Python %s, Unicode %s); DO NOT EDIT.'
      % (sys.version.split()[0], unicodedata.unidata_version))
print()
print('package monitor')
print()
print('// pyDigitExtra are the code points where str.isdigit() is true and')
print('// str.isdecimal() is not, in CPython 3.11 (sorted).')
print('var pyDigitExtra = []rune{')
for i in range(0, len(extra), 8):
    print('\t' + ' '.join('0x%X,' % s for s in extra[i:i + 8]))
print('}')
